#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    vector<int> mostVisited(int n, vector<int>& rounds) {
        int first = rounds.front(), last = rounds.back();
        vector<int> ans;
        if (first <= last) {
            for (int x = first; x <= last; ++x) ans.push_back(x);
        } else {
            for (int x = 1; x <= last; ++x) ans.push_back(x);
            for (int x = first; x <= n; ++x) ans.push_back(x);
        }
        return ans;
    }
};
